local function reset()
    bullets,enemies,powerups,drones={},{},{},{}; weapons=Weapons.new(); currentWeapon="pistol"; xpData=XP.new(); player=Player.new(love.graphics.getWidth()/2,love.graphics.getHeight()/2)
    player.fireRateMultiplier=1; player.damageMultiplier=1; player.magneticRange=0; player.piercingBullets=false; player.extraProjectiles=0; player.hasSideDrones=false; player.hasOrbitDrones=false; player.hasHomingMissile=false; player.explosionSizeMultiplier=1; player.droneDamageMultiplier=1
