local function addDrones()
    local side,orb=0,0; for _,d in ipairs(drones) do if d.formation=="side" then side=side+1 elseif d.formation=="orbit_upgrade" then orb=orb+1 end end
    if player.hasSideDrones and side<2 then for i=side+1,2 do local d=Drone.new(player.x,player.y,"attack","player"); d.formation="side"; d.formationIndex=i; d.formationCount=2; d:setQuality(quality); drones[#drones+1]=d end end
