end
local function spawnEnemy(kind,elite)
    local x,y=util.getRandomEdgePosition(); local pool={"swarmer"}; if run.wave>=2 then pool[#pool+1]="turret" end; if run.wave>=3 then pool[#pool+1]="sniper" end; if run.wave>=4 then pool[#pool+1]="bomber" end; kind=kind or pool[math.random(#pool)]
