    if elite then e.health=e.health*1.8; e.maxHealth=e.health; e.speed=e.speed*1.15; e.score=e.score*3; e.elite=true end; e._scored=false; enemies[#enemies+1]=e
end
local function boss() spawnEnemy("miniboss",false); sfx("explosion",.7); hitfx(.7,.2,1,.2); safe(camera,"shake",14,.4,2) end
local function giveReward() local w,h=love.graphics.getWidth(),love.graphics.getHeight(); local p=PowerUp.new(math.random(80,w-80),math.random(90,h-90)); p:setQuality(quality); powerups[#powerups+1]=p end
local function levelUp() state="upgrade"; _G.__SV_CHOICES=XP.getRandomUpgrades(3); sfx("levelup",.7); hitfx(.2,.8,1,.2) end
local function scoreKill(e)
    run.kills=run.kills+1; run.combo=run.combo+1; run.comboTimer=0; run.bestCombo=math.max(run.bestCombo,run.combo); run.threat=clamp(run.threat+.025,0,1)
    local m=Modes.get(run.id); local gain=(e.score or 10)*(1+math.min(run.combo,25)*.06)*m.scoreMultiplier*(m.rewardMultiplier or 1)*(e.elite and 1.75 or 1); run.score=math.floor(run.score+gain)
    local xpg=(Enemy.types[e.type] and Enemy.types[e.type].xp or 10)*m.xpMultiplier; if player.powerups.xpboost>0 then xpg=xpg*2 end; if XP.addXP(xpData,xpg) then levelUp() end
    safe(effects,"addDamageNumber",e.x,e.y,"+"..math.floor(gain),e.elite); safe(particles,"explosion",e.x,e.y,e.elite and 1.8 or .9,e.elite and "electric" or "default"); safe(camera,"shake",e.elite and 8 or 3,.1,1); sfx(e.elite and "heavyShoot" or "hit",.3); if e.elite or math.random()<.09 then giveReward() end
end
local function finish(win,msg)
    if state=="gameover" then return end; run.completed=win; reason=msg; newBest=run.score>best; best=math.max(best,run.score); state="gameover"; mouseDown=false
    if Profile.hasProfile() then Profile.updateStats(run.score,math.floor(run.score/50)); Profile.incrementGamesPlayed() end; Ads.onGameOver(run.score); sfx(win and "levelup" or "death",.8); safe(particles,"explosion",player.x,player.y,2.3,"fire")
end
local function playerDamage(amount)
    if player:takeDamage(amount) then
        run.combo=0; hitfx(1,.1,.1,.2); sfx("hit",.5); safe(camera,"shake",8,.16,2)
        if player.health<=0 then
            if run.lives>1 then
                run.lives=run.lives-1; player.health=player.maxHealth; player.powerups.invincible=2.0; bullets={}; hitfx(.2,.75,1,.24); sfx("highDown",.5); safe(effects,"notification","LIFE LOST — "..run.lives.." REMAINING",{.6,.85,1})
            else finish(false,"SHIP DESTROYED") end
        end
        return true
    end
    return false
end
local function startRun()
    reset(); state="playing"; Ads.onGameStart(); sfx("menu",.25); safe(sound,"playMusic"); local r=Modes.waveRules(run); run.target=r.target; run.spawned=0; run.spawnTimer=0; if r.boss then boss() end
end
local function advance()
    run.score=run.score+math.floor(run.wave*12*Modes.get(run.id).scoreMultiplier); sfx("highUp",.65); hitfx(.1,.8,1,.12)
    if run.id=="campaign" and run.wave>=30 then finish(true,"CAMPAIGN COMPLETE"); return end
    if run.id=="gauntlet" then if run.trial>=8 then finish(true,"GAUNTLET CLEARED"); return end; Modes.nextGauntletTrial(run) else run.wave=run.wave+1 end
    local r=Modes.waveRules(run); run.target=r.target; run.spawned=0; run.spawnTimer=0; run.trialTimer=run.trialTimer or 0; waveText=1.1; if r.boss then boss() end
end
local function shoot(a)
    local d=Weapons.types[currentWeapon]; if not d or player.shootCooldown>0 or not Weapons.hasAmmo(weapons,currentWeapon) then return end
    local n=(d.bulletCount or 1)+(player.extraProjectiles or 0); for i=1,n do local aa=a; if n>1 then aa=aa+(i-(n+1)/2)*(d.spread or 0)/n end; local b=Bullet.new(player.x,player.y,aa,"player",player.bulletColor or "yellow"); b.damage=(d.damage or 1)*10*(player.damageMultiplier or 1); b.speed=d.bulletSpeed or 400; b.vx=math.cos(aa)*b.speed; b.vy=math.sin(aa)*b.speed; b.piercing=player.piercingBullets or d.piercing; b.homing=player.powerups.homing>0; b.homingStrength=3.2; b.explosion=player.powerups.explosive>0; b.explosionRadius=42*(player.explosionSizeMultiplier or 1); bullets[#bullets+1]=b end
    Weapons.useAmmo(weapons,currentWeapon,1); player.shootCooldown=(d.fireRate or .2)*(player.fireRateMultiplier or 1); sfx((d.fireRate or .2)<.15 and "shoot" or "heavyShoot",.3); safe(particles,"thruster",player.x-math.cos(a)*12,player.y-math.sin(a)*12,a+math.pi,.8)
end
local function combat(dt)
