    local mx,my=0,0; local ax,ay=0,0; local firing=love.mouse.isDown(1); if mobile and touch then mx,my=touch:getMovement(); ax,ay=touch:getAimDirection(); firing=firing or touch:isShooting() end
    player:update(dt,mx,my,mobile and "mobile" or "pc"); local a=util.angle(player.x,player.y,love.mouse.getX(),love.mouse.getY()); if mobile and math.abs(ax)+math.abs(ay)>.1 then a=math.atan2(ay,ax); player.hasAimOverride=true; player.aimAngle=a else player.hasAimOverride=false end; if firing then shoot(a) end
    for _,b in ipairs(bullets) do b:update(dt,enemies) end
