        e:update(dt,player.x,player.y)
        if e:canShoot() then local aa=util.angle(e.x,e.y,player.x,player.y); local eb=Bullet.new(e.x,e.y,aa,"enemy",e.type=="sniper" and "blue" or "red"); eb.damage=e.damage*(Modes.waveRules(run).damageMultiplier or 1); eb.speed=e.type=="sniper" and 330 or 260; eb.vx=math.cos(aa)*eb.speed; eb.vy=math.sin(aa)*eb.speed; bullets[#bullets+1]=eb; sfx("retroShoot",.16) end
        if e.type=="miniboss" then e._t=(e._t or 1.8)-dt; if e._t<=0 then e._t=2.2; for i=1,10 do local aa=i*math.pi*.2; local eb=Bullet.new(e.x,e.y,aa,"enemy","purple"); eb.damage=e.damage*1.25; eb.speed=220; eb.vx=math.cos(aa)*eb.speed; eb.vy=math.sin(aa)*eb.speed; bullets[#bullets+1]=eb end; sfx("heavyShoot",.2) end end
    end
    for _,p in ipairs(powerups) do p:update(dt) end
    for _,d in ipairs(drones) do local a2=safe(d,"update",dt,player,enemies,bullets,powerups,{}); if a2 and a2.type=="shoot" then local b=Bullet.new(d.x,d.y,a2.angle or 0,"player",a2.color or "yellow"); b.damage=(a2.damage or 4)*(player.droneDamageMultiplier or 1); b.speed=420; b.vx=math.cos(a2.angle or 0)*b.speed; b.vy=math.sin(a2.angle or 0)*b.speed; bullets[#bullets+1]=b end end
