function love.load() math.randomseed(os.time()); Assets.load(); sound=Sound.new(); particles=Particles.new(); effects=Effects.new(); camera=Camera.new(); local os=love.system.getOS(); mobile=(os=="Android" or os=="iOS"); if mobile then touch=TouchControls.new() end; quality="high"; Profile.init(); local p=Profile.getProfile(); best=p and p.bestScore or 0; love.mouse.setVisible(true) end
function love.update(dt) dt=math.min(dt or .016,.05); time=time+dt; if waveText>0 then waveText=math.max(0,waveText-dt) end; if flashT>0 then flashT=math.max(0,flashT-dt*2.5) end; safe(particles,"update",dt); safe(effects,"update",dt); safe(camera,"update",dt); if state=="playing" then combat(dt) end end
function love.draw() love.graphics.clear(0,0,0); if state=="menu" then menu() elseif state=="modes" then modeScreen() elseif state=="playing" then world(); hud() elseif state=="upgrade" then upgradeScreen() elseif state=="gameover" then overScreen() elseif state=="help" then help() elseif state=="settings" then settings() elseif state=="paused" then world(); love.graphics.setColor(0,0,0,.65); love.graphics.rectangle("fill",0,0,love.graphics.getWidth(),love.graphics.getHeight()); local w=love.graphics.getWidth(); love.graphics.setFont(F(56)); love.graphics.setColor(1,1,1); love.graphics.printf("PAUSED",0,155,w,"center"); button({x=w/2-110,y=250,w=220,h=50,text="RESUME"}); button({x=w/2-110,y=320,w=220,h=50,text="QUIT RUN"},{.3,.42,.55}) end; if flashT>0 then love.graphics.setColor(flash[1],flash[2],flash[3],flashT*.12); love.graphics.rectangle("fill",0,0,love.graphics.getWidth(),love.graphics.getHeight()) end end
function love.mousepressed(x,y,b) if b~=1 then return end; local w,h=love.graphics.getWidth(),love.graphics.getHeight(); if state=="menu" then if inr(x,y,{x=w/2-125,y=h/2-25,w=250,h=58}) then state="modes" elseif inr(x,y,{x=w/2-125,y=h/2+50,w=250,h=58}) then state="help" elseif inr(x,y,{x=w/2-125,y=h/2+125,w=250,h=58}) then state="settings" end elseif state=="modes" then for i=1,3 do local x0=w/2-430+(i-1)*290; if inr(x,y,{x=x0,y=150,w=260,h=345}) then selectedMode=i; if y>=435 then startRun() end; return end end; if inr(x,y,{x=w/2-90,y=h-55,w=180,h=40}) then state="menu" end elseif state=="playing" then mouseDown=true elseif state=="upgrade" then local choices=_G.__SV_CHOICES or {}; for i,u in ipairs(choices) do local x0=w/2-410+(i-1)*280; if inr(x,y,{x=x0,y=190,w=250,h=210}) then pcall(u.apply,player); addDrones(); state="playing"; return end end elseif state=="gameover" then if inr(x,y,{x=w/2-220,y=465,w=200,h=55}) then startRun() elseif inr(x,y,{x=w/2+20,y=465,w=200,h=55}) then state="menu" end elseif state=="help" then state="menu" elseif state=="settings" then if inr(x,y,{x=w/2-180,y=220,w=360,h=50}) then sound:toggleSound() elseif inr(x,y,{x=w/2-180,y=290,w=360,h=50}) then sound:toggleMusic() elseif inr(x,y,{x=w/2-180,y=360,w=360,h=50}) then quality=(quality=="high" and "medium") or (quality=="medium" and "low") or "high"; particles:setQuality(quality); effects:setQuality(quality); camera:setQuality(quality) elseif inr(x,y,{x=w/2-180,y=450,w=360,h=50}) then state="menu" end elseif state=="paused" then if inr(x,y,{x=w/2-110,y=250,w=220,h=50}) then state="playing" elseif inr(x,y,{x=w/2-110,y=320,w=220,h=50}) then state="menu" end end end
function love.mousereleased(_,_,b) if b==1 then mouseDown=false end end
function love.keypressed(k) if k=="escape" then if state=="playing" then state="paused" elseif state=="paused" then state="playing" elseif state=="help" or state=="settings" or state=="modes" then state="menu" end; return end; if state=="playing" then if k=="1" then currentWeapon="pistol" elseif k=="2" and weapons.shotgun.unlocked then currentWeapon="shotgun" elseif k=="3" and weapons.machinegun.unlocked then currentWeapon="machinegun" elseif k=="4" and weapons.sniper.unlocked then currentWeapon="sniper" elseif k=="space" then dash() end elseif state=="modes" then if k=="left" or k=="a" then selectedMode=(selectedMode-2)%3+1 elseif k=="right" or k=="d" then selectedMode=selectedMode%3+1 elseif k=="return" or k=="space" then startRun() end end end
function love.touchpressed(id,x,y) if mobile and touch then if state=="playing" then touch:touchpressed(id,x,y) else love.mousepressed(x,y,1) end end end
function love.touchmoved(id,x,y) if mobile and touch and state=="playing" then touch:touchmoved(id,x,y) end end
function love.touchreleased(id) if mobile and touch and state=="playing" then touch:touchreleased(id) end end
return nil
